import cv2, numpy as np
T=cv2.cvtColor(cv2.imread('/app/target.png'),cv2.COLOR_BGR2GRAY)<100
D=cv2.distanceTransform((~T).astype(np.uint8),cv2.DIST_L2,5)
orig=np.load('/app/output/masks.npz')['masks']>0
shifts=np.zeros((4,2),int) # dx,dy

def shiftmask(m,dx,dy):
 return cv2.warpAffine(m.astype(np.uint8),np.float32([[1,0,dx],[0,1,dy]]),(1024,1024),flags=cv2.INTER_NEAREST,borderMode=cv2.BORDER_CONSTANT,borderValue=0)>0
cur=[m.copy() for m in orig]
def metrics(ms):
 A=np.logical_or.reduce(ms);tp=(A&T).sum();fp=A.sum()-tp;fn=T.sum()-tp
 iou=tp/(tp+fp+fn);stray=(A&(D>4.5)).sum()/T.sum()
 return iou,stray,int(A.sum()),int(tp),int(fn)
def obj(ms):
 i,s,*_=metrics(ms);return i-2.0*s
print('start',metrics(cur),obj(cur))
for rnd in range(3):
 changed=False
 for i in range(4):
  other=np.logical_or.reduce([cur[j] for j in range(4) if j!=i])
  best=(obj(cur),0,0,None)
  for dy in range(-8,9):
   for dx in range(-8,9):
    cand=shiftmask(orig[i],dx+shifts[i,0],dy+shifts[i,1])
    ms=[other|cand if j==i else cur[j] for j in range(4)]
    v=obj(ms)
    if v>best[0]+1e-10: best=(v,dx,dy,cand)
  if best[3] is not None:
   dx,dy=best[1:3]; shifts[i]+=[dx,dy];cur[i]=best[3];changed=True
  print(' round',rnd,'stroke',i+1,'shift',shifts[i].tolist(),'metrics',metrics(cur),'objective',round(obj(cur),6))
 if not changed: break
print('shifts dx/dy',shifts.tolist())
# best common registration shift (translation relative to target), maximize overlap
best=(-1,None,None,None)
A=np.logical_or.reduce(cur)
for dy in range(-22,23):
 for dx in range(-22,23):
  X=shiftmask(A,dx,dy); inter=(X&T).sum(); uni=(X|T).sum(); iou=inter/uni
  if iou>best[0]:best=(iou,dx,dy,X)
print('best reg',best[:3], 'registered metrics',metrics([best[3]]))
